/// A resolved set of Cloudscape colors for one mode. Read a token with
/// its getter (`colors.textBodyDefault`) or by enum (`colors[CsColor.textBodyDefault]`).
class CsColorScheme {
  const CsColorScheme(this.values);

  /// One color per [CsColor], in enum order.
  final List<Color> values;

  Color operator [](CsColor token) => values[token.index];

  /// A copy with some tokens replaced, for brand theming:
  /// `CsColorSchemes.light.copyWith({CsColor.backgroundButtonPrimaryDefault: myBlue})`.
  CsColorScheme copyWith(Map<CsColor, Color> overrides) {
    if (overrides.isEmpty) return this;
    final next = List<Color>.of(values);
    overrides.forEach((token, color) => next[token.index] = color);
    return CsColorScheme(List.unmodifiable(next));
  }

  static CsColorScheme lerp(CsColorScheme a, CsColorScheme b, double t) {
    if (identical(a, b)) return a;
    return CsColorScheme([for (var i = 0; i < a.values.length; i++) Color.lerp(a.values[i], b.values[i], t)!]);
  }

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) return true;
    if (other is! CsColorScheme || other.values.length != values.length) return false;
    for (var i = 0; i < values.length; i++) {
      if (values[i] != other.values[i]) return false;
    }
    return true;
  }

