  /// The tokens [context] overrides in [brightness] mode, relative to
  /// [light] or [dark]. Contexts with a fixed dark look (top navigation,
  /// header) return dark values in light mode too.
  static Map<CsColor, Color> contextOverrides(CsVisualContextName context, Brightness brightness) {
    final dark = brightness == Brightness.dark;
    return switch (context) {
      CsVisualContextName.topNavigation => dark ? _topNavigationDark : _topNavigationLight,
      CsVisualContextName.header => dark ? _headerDark : _headerLight,
      CsVisualContextName.appLayoutToolbar => dark ? _appLayoutToolbarDark : _appLayoutToolbarLight,
      CsVisualContextName.flashbar => dark ? _flashbarDark : _flashbarLight,
      CsVisualContextName.flashbarWarning => dark ? _flashbarWarningDark : _flashbarWarningLight,
      CsVisualContextName.alert => dark ? _alertDark : _alertLight,
      CsVisualContextName.alertHeader => dark ? _alertHeaderDark : _alertHeaderLight,
    };
  }
